struct Punkt {
    int x;
    int y;
};

// freie Funktion mit besonderem Namen
Punkt operator+(const Punkt& a, const Punkt& b) {
    return Punkt{a.x + b.x, a.y + b.y};
}

Punkt p{1, 2};
Punkt q{3, 4};
