public:
    Punkt(int x, int y) : x(x), y(y) {}

    bool operator==(const Punkt& p) const {
        return x == p.x && y == p.y;
    }

private:
    int x;
    int y;
};

Punkt a(1, 2);
Punkt b(1, 2);
Punkt c(1, 3);
