class Konto {
public:
    Konto& operator+=(int betrag) {
        stand += betrag;
        return *this;          // Referenz auf das eigene Objekt
    }

    int getStand() const {
        return stand;
    }

private:
    int stand = 0;
};

Konto k;
k += 10;
k += 5;
(k += 1) += 2;               // Kette: beide Aufrufe treffen k
