class Punkt {
public:
    Punkt(int x, int y) : x(x), y(y) {}

    // Freund: darf auf x und y zugreifen
    friend std::ostream& operator<<(std::ostream& os, const Punkt& p);

private:
    int x;
    int y;
};

std::ostream& operator<<(std::ostream& os, const Punkt& p) {
    os << "(" << p.x << ", " << p.y << ")";
    return os;
}

std::cout << Punkt(1, 2);   // (1, 2)

