class Rechner {
public:
    int quadrat(int x) const {
        ++aufrufe;           // erlaubt, weil mutable
        return x * x;
    }

    int getAufrufe() const {
        return aufrufe;
    }

private:
    mutable int aufrufe = 0;
};

const Rechner r;
r.quadrat(3);
r.quadrat(4);
std::cout << r.getAufrufe();   // 2

