#include <iostream>

class Konto {
public:
    Konto(int start) : stand(start) {}

    void einzahlen(int betrag) {
        if (betrag <= 0) {
            std::cout << "Betrag muss positiv sein\n";
            return;
        }
        stand += betrag;
    }

    int getStand() const {
        return stand;
    }

private:
    int stand;
};

int main() {
    Konto k(100);
    k.einzahlen(50);
    k.einzahlen(-20);
    std::cout << "Stand: " << k.getStand() << "\n";
    return 0;
}

