#include <iostream>

class Rechteck {
public:
    Rechteck(int breite, int hoehe) : breite(breite), hoehe(hoehe) {}

    int flaeche() const {
        return breite * hoehe;
    }

    int umfang() const {
        return 2 * (breite + hoehe);
    }

    bool ist_quadrat() const {
        return breite == hoehe;
    }

private:
    int breite;
    int hoehe;
};

int main() {
    Rechteck r(4, 5);
    std::cout << "Fläche: " << r.flaeche() << "\n";
    std::cout << "Umfang: " << r.umfang() << "\n";
    std::cout << "Quadrat: " << (r.ist_quadrat() ? "ja" : "nein") << "\n";
    return 0;
}

